import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type NotificationPopupsProps = Record<string, any>;

interface NotificationItemProps {
  data: NotificationPopupsProps["notifications"][0];
  index: number;
  totalNotifications: number;
  fps: number;
  cardBackgroundColor: string;
  textColor: string;
  subtextColor: string;
  delays: number[];
  stepHeight: number;
  itemWidth: number;
}

const NotificationItem: React.FC<NotificationItemProps> = ({ 
  data, 
  index, 
  totalNotifications,
  fps, 
  cardBackgroundColor, 
  textColor, 
  subtextColor,
  delays,
  stepHeight,
  itemWidth
}) => {
  const frame = useCurrentFrame();
  
  // Calculate total upward displacement caused by notifications appearing *after* this one
  let pushUpAmount = 0;
  for (let k = index + 1; k < totalNotifications; k++) {
    const pushAnim = spring({
      frame: frame - delays[k],
      fps,
      config: { damping: 14, stiffness: 140, mass: 0.7 }
    });
    pushUpAmount += pushAnim * stepHeight;
  }

  const delay = delays[index]; 
  const springAnim = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 140, mass: 0.7 }
  });
  
  const opacity = interpolate(springAnim, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  // Start from further down to sell the "shooting in" effect
  const entryY = interpolate(springAnim, [0, 1], [400, 0], { extrapolateRight: "clamp" });
  const scale = interpolate(springAnim, [0, 1], [0.7, 1], { extrapolateRight: "clamp" });

  // Final vertical position combines its own entry animation and the push from newer notifications
  const translateY = entryY - pushUpAmount;

  return (
    <div style={{
      position: 'absolute',
      bottom: 0,
      left: '50%',
      width: itemWidth,
      marginLeft: -(itemWidth / 2), // Center the absolute div
      zIndex: totalNotifications - index, // Older notifications sit on top of newer ones sliding in
      backgroundColor: cardBackgroundColor,
      backdropFilter: 'blur(32px)',
      WebkitBackdropFilter: 'blur(32px)',
      borderRadius: 40,
      padding: '32px 36px',
      boxSizing: 'border-box',
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      boxShadow: '0px 24px 48px rgba(0,0,0,0.12), 0px 8px 16px rgba(0,0,0,0.06), inset 0 1px 2px rgba(255,255,255,0.9)',
      border: '1px solid rgba(255,255,255,0.5)',
      gap: 24,
      opacity,
      transform: `translateY(${translateY}px) scale(${scale})`,
      transition: 'none'
    }}>
      {/* Phone Icon Container */}
      <div style={{
        width: 80, height: 80, borderRadius: 24,
        background: '#FF3B30',
        display: 'flex', justifyContent: 'center', alignItems: 'center', flexShrink: 0,
        boxShadow: '0 8px 16px rgba(255, 59, 48, 0.3)',
        transition: 'none'
      }}>
        {/* Phone Icon */}
        <svg width="40" height="40" viewBox="0 0 24 24" fill="white" stroke="none" style={{ transition: 'none' }}>
          <path d="M6.62 10.79a15.05 15.05 0 006.59 6.59l2.2-2.2a1 1 0 011.11-.21 11.72 11.72 0 003.68.59 1 1 0 011 1v3.5a1 1 0 01-1 1A19.93 19.93 0 012 4a1 1 0 011-1h3.5a1 1 0 011 1 11.72 11.72 0 00.59 3.68 1 1 0 01-.21 1.11l-2.2 2.2z" />
        </svg>
      </div>

      {/* Text Container */}
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, justifyContent: 'center', gap: 8, transition: 'none' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', transition: 'none' }}>
          <div style={{ fontSize: 28, color: textColor, letterSpacing: '-0.02em', lineHeight: 1.2, transition: 'none', maxWidth: '80%' }}>
            <span style={{ fontWeight: 700 }}>{data.username}</span>
            {data.action && <span style={{ fontWeight: 500 }}> {data.action}</span>}
          </div>
          <div style={{ fontSize: 24, fontWeight: 400, color: subtextColor, transition: 'none', marginLeft: 16 }}>
            {data.time}
          </div>
        </div>
        <div style={{ fontSize: 28, fontWeight: 400, color: textColor, letterSpacing: '-0.01em', lineHeight: 1.2, opacity: 0.9, transition: 'none' }}>
          {data.message}
        </div>
      </div>
    </div>
  );
};

const NotificationPopups: React.FC<NotificationPopupsProps> = ({
  backgroundColor = "#F3F4F6",
  transparentBackground = false,
  durationInSeconds = 12,
  cardBackgroundColor = "rgba(255, 255, 255, 0.85)",
  textColor = "#111827",
  subtextColor = "#6B7280",
  notifications = [
    { username: "Scam Likely", action: "", message: "Missed Call", time: "2h" },
    { username: "Dentist Office", action: "", message: "Missed Call", time: "1h" },
    { username: "Mom", action: "", message: "Missed Video Call", time: "45m" },
    { username: "Mom", action: "", message: "Missed Call", time: "40m" },
    { username: "Unknown Number", action: "", message: "Missed Call", time: "30m" },
    { username: "Amazon Delivery", action: "", message: "Missed Call", time: "25m" },
    { username: "Dad", action: "", message: "Missed Call", time: "20m" },
    { username: "Malloy Studio", action: "", message: "Missed Video Call", time: "15m" },
    { username: "Boss", action: "", message: "Missed Call", time: "14m" },
    { username: "Boss", action: "", message: "Missed Call (2)", time: "13m" },
    { username: "Best Friend", action: "", message: "Missed FaceTime", time: "10m" },
    { username: "Best Friend", action: "", message: "Missed Call", time: "9m" },
    { username: "Best Friend", action: "", message: "Missed Call (2)", time: "8m" },
    { username: "Best Friend", action: "", message: "Missed Call (3)", time: "7m" },
    { username: "Best Friend", action: "", message: "Missed Call (4)", time: "6m" },
    { username: "Best Friend", action: "", message: "Missed Call (5)", time: "5m" },
    { username: "Best Friend", action: "", message: "Missed Call (6)", time: "4m" },
    { username: "Best Friend", action: "", message: "Missed Call (7)", time: "3m" },
    { username: "Best Friend", action: "", message: "Missed Call (8)", time: "2m" },
    { username: "Best Friend", action: "", message: "Missed Call (9)", time: "1m" },
    { username: "Best Friend", action: "", message: "Missed Call (10)", time: "now" }
  ]
}) => {
  useFontLoader(["Inter"]);

  const { fps, width, height } = useVideoConfig();
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing targeting 9:16 portrait frames
  const itemWidth = Math.min(width * 0.9, 920);
  
  // Hardcoded card height calculation: padding(32*2) + icon(80) = 144px. Gap = 24px. Total = 168px.
  const stepHeight = 168; 

  // Compute curved delays to create a "slow then super fast" pacing effect
  const delays = React.useMemo(() => {
    let currentDelay = 0;
    return notifications.map((_, i) => {
      const delay = currentDelay;
      const progress = i / Math.max(1, notifications.length - 1);
      
      // Easing curve for the gap between notifications.
      // Starts with a wide gap (e.g., ~50 frames) and rapidly shrinks down to 2-3 frames.
      const nextGap = 2 + 50 * Math.pow(1 - progress, 3);
      currentDelay += nextGap;
      
      return delay;
    });
  }, [notifications.length]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "'Inter', sans-serif" }}>
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        width: '100%',
        height: '100%',
        transition: 'none',
        position: 'relative',
        overflow: 'hidden'
      }}>
        
        {/* Notifications Stack Container */}
        <div style={{
          position: 'absolute',
          bottom: height * 0.1, // Anchor near the bottom so they fly upwards through the screen
          left: '50%',
          width: itemWidth,
          transform: 'translateX(-50%)',
          zIndex: 10,
          transition: 'none'
        }}>
          {notifications.map((n, i) => (
            <NotificationItem 
              key={i} 
              data={n} 
              index={i} 
              totalNotifications={notifications.length}
              fps={fps} 
              cardBackgroundColor={cardBackgroundColor}
              textColor={textColor}
              subtextColor={subtextColor}
              delays={delays}
              stepHeight={stepHeight}
              itemWidth={itemWidth}
            />
          ))}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default NotificationPopups;